// Des: Tests the safety ladder, caps, quiet hours, once-only keys
// Flo: run catalog jobs in the rig > check records, counters, typed errors
// I/O: none (mock site on loopback, scratch profile) > pass or fail (skips without Chrome)
// Run: cd E:\zz-base-home\as-apps\in-inte\zr-zrow-webs && zig build test -Dfile=ru-task-runn-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const task = @import("ru-task-runn.zig"); const jobs = @import("ru-jobs-tabl.zig"); const jrun = @import("ru-jobs-main.zig"); const stat = @import("st-stat-main.zig");
fn has(rig: *rigz.Rig, needle: []const u8) bool { return std.mem.find(u8, rig.sink.items, needle) != null; }
fn fb(cx: *task.Ctx, args: task.Args) !task.Out { return jrun.runOne(cx, jobs.find("feedback-send").?, args); }
test "read and dry-run change nothing, dry-run says so" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.read); try std.testing.expectEqual(task.Out.read, try fb(&cx, .{ .text = "Hello" })); cx = rig.ctx(.dry); try std.testing.expectEqual(task.Out.dry, try fb(&cx, .{ .text = "Hello" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); try std.testing.expect(has(&rig, "dry-run: preview only")); try std.testing.expect(has(&rig, "read-only: nothing changed")); }
test "live sends; a repeat is allowed for normal jobs, caps counter counts both" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try fb(&cx, .{ .text = "Hello" })); try std.testing.expect(rig.waitPre("btn|Send|Hello", 4000)); try std.testing.expectEqual(task.Out.done, try fb(&cx, .{ .text = "Hello" })); try std.testing.expectEqual(@as(i64, 2), try rig.store.actCnt("help", 0)); }
test "once-only jobs skip the same run; unlock reopens" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); const job = jobs.find("signup").?; try std.testing.expectEqual(task.Out.done, try jrun.runOne(&cx, job, .{})); try std.testing.expectEqual(task.Out.dupe, try jrun.runOne(&cx, job, .{})); _ = rig.waitRec("btn", 3000).?; try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("btn")); }
test "daily cap stops the next run" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.capz_help_dayz = 1; var cx = rig.ctx(.live); _ = try fb(&cx, .{ .text = "first" }); try std.testing.expectError(error.CapHit, fb(&cx, .{ .text = "second" })); _ = rig.waitRec("btn", 3000).?; try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("btn")); }
test "warm-up shrinks the cap for a new account" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.warm_dayz_coun = 14; rig.conf.capz_help_dayz = 5; var cx = rig.ctx(.live); cx.now_fix = 86400000 * 100; _ = try fb(&cx, .{ .text = "one" }); try std.testing.expectError(error.CapHit, fb(&cx, .{ .text = "two" })); }
test "quiet hours block live, dry-run only warns" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.quie_hour_rang = .{ 0, 23 }; rig.conf.quie_zone_minu = 0; var cx = rig.ctx(.live); cx.now_fix = 12 * 3600000; try std.testing.expectError(error.QuietHour, fb(&cx, .{ .text = "night" })); cx = rig.ctx(.dry); cx.now_fix = 12 * 3600000; try std.testing.expectEqual(task.Out.dry, try fb(&cx, .{ .text = "night" })); try std.testing.expect(has(&rig, "a live run would stop now")); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
test "risky act needs --force, then goes through; no consent = refused" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); const job = jobs.find("key-revoke").?; try std.testing.expectError(error.NeedApprove, jrun.runOne(&cx, job, .{})); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); cx = rig.ctx(.force); try std.testing.expectEqual(task.Out.done, try jrun.runOne(&cx, job, .{})); try std.testing.expect(rig.waitPre("btn|Delete key", 4000)); try rig.store.metaSet("consent", 0); cx = rig.ctx(.live); try std.testing.expectError(error.NoConsent, fb(&cx, .{ .text = "x" })); }
test "a key left pending (crash after submit) refuses, unlock reopens" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); const job = jobs.find("signup").?; const path = try jrun.pathOf(&cx, job, .{}); const all = try std.fmt.allocPrint(cx.aren, "{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}|{s}", .{ path, "", "", "", "", "", "", "", "", "", "", "" }); const hsh = try task.hashHex(&cx, all); const key = try std.fmt.allocPrint(cx.aren, "job|signup|{s}", .{hsh}); try std.testing.expectEqual(stat.Take.go, try rig.store.keyTake(key, 1)); try std.testing.expectError(error.Dupe, jrun.runOne(&cx, job, .{})); try std.testing.expect(has(&rig, "zr unlock")); try rig.store.keyDrop(key); try std.testing.expectEqual(task.Out.done, try jrun.runOne(&cx, job, .{})); }
test "failure before submit keeps the key free: fix the label and retry works" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.retr_coun_maxz = 1; const good = rig.conf.labl_over; var aren = std.heap.ArenaAllocator.init(std.testing.allocator); defer aren.deinit(); const bad = try @import("cf-conf-load.zig").confParse(aren.allocator(), "{\"labl_over\":{\"emai_boxz\":[\"zzz no such\"]}}"); rig.conf.labl_over = bad.labl_over; var cx = rig.ctx(.live); const job = jobs.find("signup").?; try std.testing.expectError(error.NoElement, jrun.runOne(&cx, job, .{})); rig.conf.labl_over = good; cx = rig.ctx(.live); try std.testing.expectEqual(task.Out.done, try jrun.runOne(&cx, job, .{})); }
test "halt page mid-flow: nothing written, error is Halted, halt is logged" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var cx = rig.ctx(.live); try std.testing.expectError(error.Halted, jrun.runOne(&cx, jobs.find("page-open").?, .{ .url = "/captcha" })); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); const rows = try rig.store.logRecent(cx.aren, 5); var seen = false; for (rows) |row| { if (std.mem.eql(u8, row.kind, "halt") and std.mem.eql(u8, row.what, "captcha")) seen = true; } try std.testing.expect(seen); }
